solution.solution.cpp:
#include <cctype>
#include <cstdint>
#include <cstdio>
#include <map>
#include <string>
#include <vector>

struct BugCheck { std::uint32_t code; std::uint64_t p[4]; };

namespace
{
    bool hexNumber(const std::string& s, std::uint64_t& v)
    {
        if (s.size() < 3 || s.size() > 18 || s[0] != '0' || (s[1] != 'x' && s[1] != 'X')) return false;
        v = 0;
        for (std::size_t i{ 2 }; i < s.size(); ++i)
        {
            const char c{ static_cast<char>(std::tolower(static_cast<unsigned char>(s[i]))) };
            int d;
            if (c >= '0' && c <= '9') d = c - '0';
            else if (c >= 'a' && c <= 'f') d = c - 'a' + 10;
            else return false;
            v = v * 16 + static_cast<std::uint64_t>(d);
        }
        return true;
    }

    std::string trim(const std::string& s)
    {
        const auto b{ s.find_first_not_of(' ') };
        if (b == std::string::npos) return "";
        return s.substr(b, s.find_last_not_of(' ') - b + 1);
    }

    std::string hex16(std::uint64_t v)
    {
        char buffer[24];
        std::snprintf(buffer, sizeof(buffer), "0x%016llX", static_cast<unsigned long long>(v));
        return buffer;
    }
}

bool parseBugCheck(const std::string& line, BugCheck& out)
{
    const std::string head{ "*** Fatal System Error: " };
    if (line.rfind(head, 0) != 0) return false;
    const std::string rest{ line.substr(head.size()) };
    const auto open{ rest.find(" (") };
    if (open == std::string::npos || rest.back() != ')') return false;
    std::uint64_t code{ 0 };
    if (!hexNumber(rest.substr(0, open), code) || code > 0xFFFFFFFFu) return false;
    const std::string inside{ rest.substr(open + 2, rest.size() - open - 3) };
    std::vector<std::string> parts;
    std::string part;
    for (char c : inside) { if (c == ',') { parts.push_back(trim(part)); part.clear(); } else part += c; }
    parts.push_back(trim(part));
    if (parts.size() != 4) return false;
    BugCheck b{ static_cast<std::uint32_t>(code), {} };
    for (int i{ 0 }; i < 4; ++i) if (!hexNumber(parts[static_cast<std::size_t>(i)], b.p[i])) return false;
    out = b;
    return true;
}

std::string bugCheckName(std::uint32_t code)
{
    static const std::map<std::uint32_t, std::string> names{
        { 0x0A, "IRQL_NOT_LESS_OR_EQUAL" }, { 0x3B, "SYSTEM_SERVICE_EXCEPTION" }, { 0x50, "PAGE_FAULT_IN_NONPAGED_AREA" },
        { 0x7E, "SYSTEM_THREAD_EXCEPTION_NOT_HANDLED" }, { 0xC4, "DRIVER_VERIFIER_DETECTED_VIOLATION" },
        { 0xCE, "DRIVER_UNLOADED_WITHOUT_CANCELLING_PENDING_OPERATIONS" }, { 0xD1, "DRIVER_IRQL_NOT_LESS_OR_EQUAL" } };
    const auto it{ names.find(code) };
    return it == names.end() ? "UNKNOWN_BUG_CHECK" : it->second;
}

std::string explain(const BugCheck& b)
{
    if (b.code == 0xD1 || b.code == 0x0A)
    {
        const char* kind{ b.p[2] == 0 ? "read" : b.p[2] == 1 ? "write" : b.p[2] == 8 ? "execute" : "access" };
        return std::string(kind) + " of " + hex16(b.p[0]) + " at IRQL " + std::to_string(b.p[1]);
    }
    if (b.code == 0x50) return std::string(b.p[1] == 0 ? "read" : "write") + " of invalid address " + hex16(b.p[0]);
    return bugCheckName(b.code);
}

unitTests:
TEST("parsing") {
    BugCheck b{};
    CHECK(parseBugCheck("*** Fatal System Error: 0x000000d1 (0xFFFFA00012345678,0x0000000000000002,0x0000000000000000,0xFFFFF80123456789)", b));
    CHECK_EQ(b.code, 0xD1u); CHECK_EQ(b.p[0], 0xFFFFA00012345678ull); CHECK_EQ(b.p[1], 2ull); CHECK_EQ(b.p[3], 0xFFFFF80123456789ull);
    CHECK(parseBugCheck("*** Fatal System Error: 0x00000050 (0x10, 0x1, 0xFFFFF80000001000, 0x2)", b)); CHECK_EQ(b.p[1], 1ull);
}
TEST("not a bug check line") {
    BugCheck b{}; CHECK(!parseBugCheck("Fatal System Error: 0xd1 (0x1,0x2,0x3,0x4)", b)); CHECK(!parseBugCheck("*** Fatal System Error: 0xd1 (0x1,0x2,0x3)", b));
    CHECK(!parseBugCheck("*** Fatal System Error: 0xd1 (0x1,0x2,0x3,0xG)", b)); CHECK(!parseBugCheck("*** Fatal System Error: d1 (0x1,0x2,0x3,0x4)", b));
}
TEST("names") { CHECK_EQ(bugCheckName(0xD1), std::string("DRIVER_IRQL_NOT_LESS_OR_EQUAL")); CHECK_EQ(bugCheckName(0xC4), std::string("DRIVER_VERIFIER_DETECTED_VIOLATION")); CHECK_EQ(bugCheckName(0x1234), std::string("UNKNOWN_BUG_CHECK")); }
TEST("explanations") {
    CHECK_EQ(explain({ 0xD1, { 0xFFFFA00012345678ull, 2, 0, 0 } }), std::string("read of 0xFFFFA00012345678 at IRQL 2"));
    CHECK_EQ(explain({ 0x0A, { 0x10, 2, 1, 0 } }), std::string("write of 0x0000000000000010 at IRQL 2"));
    CHECK_EQ(explain({ 0x50, { 0xFFFFF80000001000ull, 0, 0, 0 } }), std::string("read of invalid address 0xFFFFF80000001000"));
    CHECK_EQ(explain({ 0xCE, { 0, 0, 0, 0 } }), std::string("DRIVER_UNLOADED_WITHOUT_CANCELLING_PENDING_OPERATIONS"));
}

